INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('kitchen-court', 1, 'Kitchen Court', 'In a house where Mom is a real judge, every family fight goes to trial at the kitchen table, and when the kids sue their parents, a kid presides.', 'Renata never gets reversed downtown. At home she is 0 and 4 this week, and one of those was a first-grader. The gavel is a potato masher. The timer is a slice of toast. Every verdict ends in a snack, a hug, and a whistle.', 'Comedy', 'Family', '22 min', NULL, 90, 28, 'trailer', 1);
INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('long-route', 2, 'Long Route', 'Six kids ride the county''s last long school bus route for 48 minutes twice a day, and the bus is where everything that happens to them actually happens.', 'The back row runs a parliament. The front row keeps the ledger. Frances has driven the route for thirty years and drives with her ears. Now a man from the county is on board with a stopwatch.', 'Comedy', 'Family', '22 min', NULL, 90, 205, 'trailer', 2);
INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('recent-history-society', 3, 'Recent History Society', 'A neighborhood historical society reenacts only what happened last week, in full costume, with total seriousness, and a grandfather and his granddaughter run it.', 'Last Tuesday, a soup pyramid fell in aisle five. The Society will get it right if it takes all night. Piper, ten, plays the pyramid. Dale plays the horse. Dale always plays the horse.', 'Variety', 'Family', '12 min', NULL, 73, 330, 'premiere', 3);
INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('the-returns-desk', 4, 'The Returns Desk', 'At the all-night returns desk of a neighborhood hardware store, every item comes back with a ghost story, and the desk always finds the ordinary truth.', 'After hours, the returns desk takes back the things nobody wants. Some of them hum. Some of them ring. Marguerite believes every story and processes the return by policy anyway. Ines, twelve, keeps the ledger of causes. There is one blank tag on the shelf.', 'Anthology', 'Family', '18 min', NULL, 120, 262, 'trailer', 4);
